import { useEffect, useState } from "react";
import AuthPage from "./login";
import Main from "./pages/Main";

function App() {
  const [isLogin, setIsLogin] = useState(false);

  useEffect(() => {
    const loginStatus = localStorage.getItem("isLogin");
    if (loginStatus === "true") {
      setIsLogin(true);
    }
  }, []);

  return (
    <>
      {isLogin ? <Main /> : <AuthPage />}
    </>
  );
}

export default App;
